def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    components = []
    while cells:
        start = cells.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in cells:
                        cells.remove(p)
                        comp.add(p)
                        stack.append(p)
        components.append(comp)

    shape = max(components, key=len)
    sr = min(r for r, c in shape)
    sc = min(c for r, c in shape)
    er = max(r for r, c in shape)
    ec = max(c for r, c in shape)
    center_r = (sr + er) // 2
    center_c = (sc + ec) // 2
    pattern = [(r - center_r, c - center_c, grid[r][c]) for r, c in shape]

    markers = [next(iter(comp)) for comp in components if comp is not shape and len(comp) == 1]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        out[mr][mc] = bg
        for dr, dc, value in pattern:
            r, c = mr + dr, mc + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = value
    return out
